<script setup lang="ts">import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';const router=useRouter();const identity=localStorage.getItem('username')||'教师';const logout=()=>{localStorage.clear();router.replace('/login')};const exams=ref<any[]>([]);const selected=ref('10000000-0000-0000-0000-000000000001');async function load(){exams.value=[{id:selected.value,title:'LabProctor 模拟考试',status:'进行中'}]}function download(path:string){window.open(`/api/v1/teacher/exams/${selected.value}/exports/${path}`,'_blank')}onMounted(load)</script>
<template><main><header><h1>教师考务管理中心</h1><span>教师：{{identity}} <button @click="logout">退出登录</button></span></header><label>考试列表：<select v-model="selected"><option v-for="e in exams" :value="e.id">{{e.title}} · {{e.status}}</option></select></label><div class="actions"><button @click="download('sources.zip')">📥 导出学生纯源码（ZIP - 不含模板）</button><button @click="download('grades.xlsx')">📊 导出全场成绩单（Excel）</button><button @click="download('screen-logs.xlsx')">📋 导出切屏作弊明细日志（Excel）</button><RouterLink :to="`/teacher/exams/${selected}/proctor`">进入实时监考大屏</RouterLink><RouterLink :to="`/teacher/exams/${selected}/review`">进入人工阅卷</RouterLink></div></main></template><style scoped>main{padding:32px;font:16px system-ui}header{display:flex;justify-content:space-between;align-items:center}.actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:24px}button,a{padding:10px;background:#1f4b99;color:#fff;border:0;border-radius:5px;text-decoration:none;cursor:pointer}</style>
